class BalancedBrackets:
    LEFT_PAREN = "("
    RIGHT_PAREN = ")"
    LEFT_BRACE = "{"
    RIGHT_BRACE = "}"
    LEFT_BRACKET = "["
    RIGHT_BRACKET = "]"

    def __init__(self, expr):
        self._stack = []
        self._left_brackets = [self.LEFT_PAREN, self.LEFT_BRACE, self.LEFT_BRACKET]
        self._right_brackets = [self.RIGHT_PAREN, self.RIGHT_BRACE, self.RIGHT_BRACKET]
        self._expr = expr

    @property
    def stack(self):
        return self._stack

    @property
    def expr(self):
        return self._expr

    @property
    def left_brackets(self):
        return self._left_brackets

    @property
    def right_brackets(self):
        return self._right_brackets

    def clear_expr(self):
        self._expr = ''.join(c for c in self._expr if (c in self._left_brackets or c in self._right_brackets))

    def is_matching_pair(self, left_brkt, right_brkt):
        if left_brkt == self.LEFT_PAREN:
            return right_brkt == self.RIGHT_PAREN
        if left_brkt == self.LEFT_BRACE:
            return right_brkt == self.RIGHT_BRACE
        if left_brkt == self.LEFT_BRACKET:
            return right_brkt == self.RIGHT_BRACKET
        return False

    def check_balanced_brackets(self):
        self.clear_expr()
        for brkt in self._expr:
            if brkt in self._left_brackets:
                self._stack.append(brkt)
            else:
                current_brkt = self._stack.pop()
                if not self.is_matching_pair(current_brkt, brkt):
                    return False
        if self._stack:
            return False
        return True
